          <button
            type="button"
            aria-expanded={open}
            aria-label={`Toggle ${label} menu`}
            onClick={() => setOpen((value) => !value)}
            className="p-1"
          >
            <svg
              viewBox="0 0 24 24"
              aria-hidden="true"
              className={cn(
                'h-3 w-3 transition-transform',
                open && 'rotate-180',
              )}
              fill="none"
              stroke="currentColor"
              strokeWidth="2.5"
            >
              <path d="M5 8l7 7 7-7" strokeLinecap="round" />
