        )}
      </div>

      {hasPanel && open && (
        <div className="z-50 mt-1 w-full rounded-xl border border-gray-200 bg-white p-4 text-gray-900 shadow-lg lg:absolute lg:top-full lg:left-0 lg:mt-0 lg:w-max lg:min-w-64">
          {panel}
        </div>
      )}
    </li>
  );
};

